+        function measure() {
+          const gap = 14;
+          const cardWidth = track.querySelector(".product-card")?.getBoundingClientRect().width ?? 290;
+          const viewportWidth = viewport.getBoundingClientRect().width;
+          const visibleCount = Math.max(1, Math.floor((viewportWidth - 20) / (cardWidth + gap)));
+          state.step = cardWidth + gap;
+          state.maxIndex = Math.max(0, featuredProducts.length - visibleCount);
+          state.index = Math.min(state.index, state.maxIndex);
+          apply();
+        }
+
+        function apply() {
+          state.x = -(state.index * state.step);
+          track.style.setProperty("--x", `${state.x}px`);
